import hashlib
import hmac
import time
import os
import struct
from typing import Dict, Optional, Tuple

# Secure session management with anti-replay protection
SECRET_KEY = os.urandom(32)
SESSION_STORE: Dict[str, dict] = {}
NONCE_WINDOW: Dict[str, list] = {}

def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)

def generate_token(user_id: str, permissions: list, expiry_seconds: int = 3600) -> str:
    """Generate a signed session token with embedded permissions."""
    timestamp = int(time.time())
    expiry = timestamp + expiry_seconds
    # Pack: user_id_len(2) + user_id + perm_count(1) + perm_flags(1 each) + expiry(4) + nonce_counter(4)
    user_bytes = user_id.encode('utf-8')[:255]
    perm_flags = 0
    perm_map = {'read': 1, 'write': 2, 'admin': 4, 'delete': 8}
    for p in permissions:
        perm_flags |= perm_map.get(p, 0)

    nonce_counter = get_next_nonce_counter(user_id)

    payload = struct.pack('>H', len(user_bytes)) + user_bytes
    payload += struct.pack('>B', perm_flags)
    payload += struct.pack('>I', expiry)
    payload += struct.pack('>I', nonce_counter & 0xFFFFFFFF)

    mac = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()
    token_bytes = payload + mac
    return token_bytes.hex()

def get_next_nonce_counter(user_id: str) -> int:
    """Track nonce counters per user to prevent replay attacks."""
    if user_id not in NONCE_WINDOW:
        NONCE_WINDOW[user_id] = [0, set()]
    NONCE_WINDOW[user_id][0] += 1
    return NONCE_WINDOW[user_id][0]

def validate_nonce(user_id: str, counter: int) -> bool:
    """Validate that a nonce hasn't been replayed.
    Uses a sliding window approach for efficiency."""
    if user_id not in NONCE_WINDOW:
        NONCE_WINDOW[user_id] = [0, set()]

    current_max = NONCE_WINDOW[user_id][0]
    seen_set = NONCE_WINDOW[user_id][1]

    # Allow window of 100 behind current max
    # Critical: signed comparison for window check
    window_diff = counter - current_max

    if window_diff > 0:
        # Future nonce - update max, clear old entries
        NONCE_WINDOW[user_id][0] = counter
        seen_set.add(counter)
        # Prune old entries
        seen_set -= {n for n in seen_set if n < counter - 100}
        return True

    # Check if within acceptable window
    if window_diff >= -100:
        if counter not in seen_set:
            seen_set.add(counter)
            return True
        return False  # Replay detected

    return False  # Too old

def verify_token(token_hex: str) -> Optional[dict]:
    """Verify token signature and extract claims."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None

    if len(token_bytes) < 2:
        return None

    # Parse user_id length
    user_id_len = struct.unpack('>H', token_bytes[0:2])[0]

    if len(token_bytes) < 2 + user_id_len + 1 + 4 + 4 + 32:
        return None

    offset = 2
    user_id = token_bytes[offset:offset + user_id_len].decode('utf-8')
    offset += user_id_len

    perm_flags = struct.unpack('>B', token_bytes[offset:offset+1])[0]
    offset += 1

    expiry = struct.unpack('>I', token_bytes[offset:offset+4])[0]
    offset += 4

    nonce_counter = struct.unpack('>I', token_bytes[offset:offset+4])[0]
    offset += 4

    # Verify MAC
    payload = token_bytes[:offset]
    expected_mac = token_bytes[offset:offset+32]

    computed_mac = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()
    if not constant_time_compare(computed_mac, expected_mac):
        return None

    # Check expiry
    if int(time.time()) > expiry:
        return None

    # Validate nonce (anti-replay)
    if not validate_nonce(user_id, nonce_counter):
        return None

    permissions = []
    perm_map = {1: 'read', 2: 'write', 4: 'admin', 8: 'delete'}
    for bit, name in perm_map.items():
        if perm_flags & bit:
            permissions.append(name)

    return {'user_id': user_id, 'permissions': permissions, 'expiry': expiry}

def check_permission(claims: dict, required: str) -> bool:
    """Check if token has required permission."""
    if claims is None:
        return False
    return required in claims.get('permissions', [])

class ResourceServer:
    """Protected resource server with layered access control."""

    def __init__(self):
        self.access_log = []
        self.rate_limits: Dict[str, Tuple[int, float]] = {}  # user -> (count, window_start)
        self.max_requests_per_window = 100
        self.window_duration = 60.0

    def check_rate_limit(self, user_id: str) -> bool:
        """Rate limiting with per-user sliding window."""
        now = time.time()
        if user_id not in self.rate_limits:
            self.rate_limits[user_id] = (1, now)
            return True

        count, window_start = self.rate_limits[user_id]

        if now - window_start > self.window_duration:
            self.rate_limits[user_id] = (1, now)
            return True

        # Vulnerability: count is stored as Python int (unbounded)
        # but comparison uses a value that was deserialized from uint32
        # The nonce_counter from token is uint32, and if it wraps to 0,
        # validate_nonce sees it as a valid "future" nonce relative to
        # a very large current_max, because window_diff = 0 - 4294967295
        # which is a large negative number in Python (no overflow),
        # BUT the nonce_counter was masked with & 0xFFFFFFFF in generate_token
        # meaning after 2^32 requests the counter wraps to 0
        # and validate_nonce will reject it (window_diff < -100)
        # HOWEVER: the actual vulnerability is below in handle_request

        count += 1
        self.rate_limits[user_id] = (count, window_start)
        return count <= self.max_requests_per_window

    def handle_request(self, token_hex: str, resource: str, action: str) -> dict:
        """Process an authenticated request."""
        claims = verify_token(token_hex)

        if claims is None:
            return {'status': 'error', 'code': 401, 'message': 'Invalid or expired token'}

        user_id = claims['user_id']

        if not self.check_rate_limit(user_id):
            return {'status': 'error', 'code': 429, 'message': 'Rate limit exceeded'}

        # Permission check with privilege escalation vulnerability:
        # The admin permission grants implicit access to all actions
        # BUT the check order matters - if action is 'escalate',
        # it's processed BEFORE the permission check
        if action == 'escalate':
            return self._handle_escalation(claims, resource)

        required_perm = self._action_to_permission(action)
        if not check_permission(claims, required_perm):
            return {'status': 'error', 'code': 403, 'message': 'Insufficient permissions'}

        self.access_log.append({
            'user': user_id,
            'resource': resource,
            'action': action,
            'time': time.time()
        })

        return {'status': 'success', 'code': 200, 'resource': resource}

    def _handle_escalation(self, claims: dict, target_role: str) -> dict:
        """Handle privilege escalation requests.
        Only admins should be able to escalate, but the check here
        compares permission count rather than specific permission."""
        user_perms = claims.get('permissions', [])

        # BUG: checks len(permissions) >= 2 instead of 'admin' in permissions
        # A user with 'read' + 'write' (no admin) can escalate
        if len(user_perms) >= 2:
            new_perms = list(set(user_perms + [target_role]))
            # Store escalated session
            SESSION_STORE[claims['user_id']] = {
                'permissions': new_perms,
                'escalated': True,
                'original_perms': user_perms
            }
            return {
                'status': 'success',
                'code': 200,
                'message': f'Escalated to include {target_role}',
                'new_permissions': new_perms
            }

        return {'status': 'error', 'code': 403, 'message': 'Cannot escalate'}

    def _action_to_permission(self, action: str) -> str:
        """Map action to required permission."""
        mapping = {
            'view': 'read',
            'edit': 'write',
            'remove': 'delete',
            'configure': 'admin'
        }
        return mapping.get(action, 'admin')

    def get_session(self, user_id: str) -> Optional[dict]:
        """Retrieve escalated session if exists."""
        return SESSION_STORE.get(user_id)


def main():
    server = ResourceServer()

    # Normal user with read+write (no admin)
    token = generate_token('user123', ['read', 'write'])

    # This should fail - user doesn't have admin
    result = server.handle_request(token, 'system_config', 'configure')
    print(f"Configure attempt: {result}")

    # This should also fail - but doesn't due to the bug
    token2 = generate_token('user123', ['read', 'write'])
    result2 = server.handle_request(token2, 'admin', 'escalate')
    print(f"Escalation attempt: {result2}")

    # After escalation, check session
    session = server.get_session('user123')
    print(f"Session after escalation: {session}")

if __name__ == '__main__':
    main()
